def transform(grid):
    out=[row[:] for row in grid]
    p7=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==7]
    p9=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==9]
    if not p7 or not p9:
        return out
    r7=[p[0] for p in p7]; c7=[p[1] for p in p7]
    r9=[p[0] for p in p9]; c9=[p[1] for p in p9]
    a=(min(r7),max(r7),min(c7),max(c7))
    b=(min(r9),max(r9),min(c9),max(c9))
    for r,c in p7: out[r][c]=6
    for r,c in p9: out[r][c]=7
    if a[0]>b[1] or a[1]<b[0]:
        lo,hi=sorted((a[0],b[0]))
        for r in range(lo,hi+1):
            if any(v==0 for v in grid[r]):
                for c in range(b[2],b[3]+1):
                    if out[r][c]==6: out[r][c]=2
    elif a[2]>b[3]:
        zs=[c for c in range(b[3]+1,a[2]) if any(grid[r][c]==0 for r in range(len(grid)))]
        shift=-1 if zs and zs[0]-b[3]==3 else 0
        for c in zs:
            for r in range(b[0],b[1]+1):
                if out[r][c+shift]==6: out[r][c+shift]=2
    else:
        zs=[c for c in range(a[3]+1,b[2]) if any(grid[r][c]==0 for r in range(len(grid)))]
        for c in zs:
            for r in range(b[0],b[1]+1):
                if out[r][c]==6: out[r][c]=2
    return out

